// Shared category shape; identifiers and ownership are generated by Postgres.
export type Category = {
  id: string; workspace_id: string; name: string; created_by: string;
  created_at: string; updated_at: string;
};

// Trim and bound names before they reach database constraints.
export function categoryName(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const name = value.trim();
  return name && [...name].length <= 120 ? name : null;
}
